function onLoad()
    self.createButton({
        click_function = "plus_power",
        function_owner = self,
        label          = "+1 Power",
        position       = {0, 3, 0},
        rotation       = {0, 0, 0},
        width          = 1500,
        height         = 400,
        font_size      = 340,
        color          = {0.5, 0.5, 0.5},
        font_color     = {1, 1, 1},
    })
end

function plus_power()
    print("White +1 Power")
    self.takeObject({
        position = {x=0, y=5, z=0},
    })
end

